package main
import("bytes";"encoding/json";"io";"mime/multipart";"net/http";"net/http/httptest";"os";"path/filepath";"strings";"testing";"time")
func demoApp(t *testing.T)*guiApp{t.Helper();a,e:=newGUIApp(true,"demo");if e!=nil{t.Fatal(e)};t.Cleanup(func(){os.RemoveAll(a.temp)});return a}
func requestGUI(a *guiApp,method,path,body string)*httptest.ResponseRecorder{r:=httptest.NewRequest(method,path,strings.NewReader(body));r.Header.Set("Authorization","Bearer "+a.token);w:=httptest.NewRecorder();a.serveHTTP(w,r);return w}
func waitGUI(t *testing.T,a *guiApp){t.Helper();for end:=time.Now().Add(8*time.Second);time.Now().Before(end);{if !a.snapshot().Busy{return};time.Sleep(10*time.Millisecond)};t.Fatal("job timeout")}
func TestGUISecurity(t *testing.T){a:=demoApp(t);r:=httptest.NewRequest("GET","/api/state",nil);w:=httptest.NewRecorder();a.serveHTTP(w,r);if w.Code!=401{t.Fatal(w.Code)};r.Header.Set("Authorization","Bearer "+a.token);r.Header.Set("Origin","https://evil.example");w=httptest.NewRecorder();a.serveHTTP(w,r);if w.Code!=403{t.Fatal(w.Code)};a.base="http://127.0.0.1:12345";if requestGUI(a,"GET","/api/state","").Code!=403{t.Fatal("host guard")};a.base="";if requestGUI(a,"GET","/gui.go","").Code!=404{t.Fatal("source exposed")};if requestGUI(a,"GET","/api/flash","").Code!=405{t.Fatal("method guard")}}
func TestGUIDemoFlashAndCancel(t *testing.T){a:=demoApp(t);ds,_:=a.disks();id:=a.opaque(ds[0].Identity);if requestGUI(a,"POST","/api/flash",`{"card_id":"`+id+`"}`).Code!=400{t.Fatal("confirmation absent")};body:=`{"card_id":"`+id+`","confirm":"ERASE:`+id+`"}`;if requestGUI(a,"POST","/api/flash",body).Code!=202{t.Fatal("not started")};if requestGUI(a,"POST","/api/quit",`{}`).Code!=409{t.Fatal("quit busy")};if requestGUI(a,"POST","/api/flash",body).Code!=400{t.Fatal("parallel job")};requestGUI(a,"POST","/api/cancel",`{}`);waitGUI(t,a);if a.snapshot().Job.Status!="error"{t.Fatal("cancel")};if requestGUI(a,"POST","/api/flash",body).Code!=202{t.Fatal("retry")};waitGUI(t,a);if a.snapshot().Job.Status!="done"{t.Fatal(a.snapshot().Job)};if a.snapshot().Image.Path!=""{t.Fatal("real image used")}}
func uploadGUI(t *testing.T,a *guiApp,path,id,name string,data []byte)*httptest.ResponseRecorder{t.Helper();var buf bytes.Buffer;mw:=multipart.NewWriter(&buf);if id!=""{mw.WriteField("inbox_id",id)};field:="files";if path=="image"{field="image"};p,_:=mw.CreateFormFile(field,name);p.Write(data);mw.Close();r:=httptest.NewRequest("POST","/api/"+path,&buf);r.Header.Set("Authorization","Bearer "+a.token);r.Header.Set("Content-Type",mw.FormDataContentType());w:=httptest.NewRecorder();a.serveHTTP(w,r);return w}
func TestGUIImportsAndInvalidImage(t *testing.T){a:=demoApp(t);vs,_:=a.inboxes();id:=a.opaque(vs[0].Description);apk:=apkFixture(t,24,"armeabi-v7a",false);b,_:=os.ReadFile(apk);w:=uploadGUI(t,a,"apks",id,"game.apk",b);if w.Code!=202{t.Fatal(w.Body.String())};waitGUI(t,a);if a.snapshot().Job.Status!="done"{t.Fatal(a.snapshot().Job)};w=uploadGUI(t,a,"obbs",id,"main.1.com.example.game.obb",[]byte("game data"));if w.Code!=202{t.Fatal(w.Body.String())};waitGUI(t,a);if a.snapshot().Job.Status!="done"{t.Fatal(a.snapshot().Job)};w=requestGUI(a,"GET","/api/log?id="+id,"");if w.Code!=http.StatusOK{t.Fatal(w.Body.String())};var log map[string]string;json.Unmarshal(w.Body.Bytes(),&log);if !strings.Contains(log["text"],"DEMO"){t.Fatal(log)};old:=a.snapshot().Image.Name;w=uploadGUI(t,a,"image","","bad.img.gz",[]byte("not gzip"));if w.Code!=202{t.Fatal(w.Body.String())};waitGUI(t,a);if a.snapshot().Job.Status!="error"||a.snapshot().Image.Name!=old{t.Fatal("invalid image accepted")};files,_:=filepath.Glob(filepath.Join(a.temp,"image-*"));if len(files)!=0{t.Fatal("failed upload not cleaned")};for i:=0;i<200;i++{a.event("event")};if len(a.snapshot().Events)!=150{t.Fatal("unbounded log")}}
func TestGUIStatic(t *testing.T){a:=demoApp(t);for _,p:=range []string{"/","/app.js","/style.css"}{w:=requestGUI(a,"GET",p,"");b,_:=io.ReadAll(w.Result().Body);if w.Code!=200||len(b)==0{t.Fatal(p)}}}
